#!/usr/bin/env python3
"""Render docs/observability/metric-registry.md: every metric bff-signup emits,
from two sources of truth. Adapted from iam-org-membership's script.

  * The Platform Observability Registry shipped with the pinned
    platform-gincommon (internal/obsregistry/registry.json): the Tier 1
    metrics platform-gincommon's HTTP server and build-info emit, the Tier 1
    collectors this service builds itself (gincommon.NewShared*Vec), and the
    Tier 2 bff_* entries (none yet).
  * A real /metrics scrape (TestStandard_AllCollectorsRegistered, which records
    one sample on every collector this service owns): every Tier 3
    bff_signup_* metric with its type, labels and help text.

Usage: metrics-inventory.py <registry.json> <scrape.txt> <gincommon-version>
Writes the Markdown to stdout. Run through `make metrics-inventory`; CI fails
when the committed file differs (.github/scripts/metricslint.sh).
"""
import json
import re
import sys

LIBRARIES = ("platform-gincommon",)
IGNORED_LABELS = {"domain", "service", "environment", "le", "quantile"}
SERVICE_PREFIX = "bff_signup_"
DOMAIN_PREFIX = "bff_"


def md(text):
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def parse_scrape(path):
    """Return {family: {"type", "help", "labels"}} from Prometheus text."""
    families = {}
    for line in open(path, encoding="utf-8"):
        line = line.rstrip("\n")
        if line.startswith("# HELP "):
            name, _, help_text = line[len("# HELP "):].partition(" ")
            families.setdefault(name, {"labels": set()})["help"] = help_text
        elif line.startswith("# TYPE "):
            name, _, mtype = line[len("# TYPE "):].partition(" ")
            families.setdefault(name, {"labels": set()})["type"] = mtype
        elif line and not line.startswith("#"):
            m = re.match(r"([a-zA-Z_:][a-zA-Z0-9_:]*)(\{([^}]*)\})?", line)
            if not m:
                continue
            series = m.group(1)
            family = series
            for suffix in ("_bucket", "_sum", "_count"):
                if series.endswith(suffix) and series[: -len(suffix)] in families:
                    family = series[: -len(suffix)]
            labels = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="', m.group(3) or "")
            families.setdefault(family, {"labels": set()})["labels"].update(
                label for label in labels if label not in IGNORED_LABELS
            )
    return families


def labels_cell(entry):
    labels = entry.get("labels") or []
    if not labels:
        return "-"
    cell = ", ".join(f"`{label}`" for label in labels)
    for label, values in sorted((entry.get("label_values") or {}).items()):
        cell += f"<br>`{label}` ∈ " + ", ".join(f"`{v}`" for v in values)
    return cell


def type_cell(entry):
    mtype = entry.get("type", "")
    if mtype == "histogram" and entry.get("buckets"):
        return f"histogram ({entry['buckets']})"
    return mtype


def main():
    registry_path, scrape_path, gincommon_version = sys.argv[1:4]
    registry = json.load(open(registry_path, encoding="utf-8"))
    scrape = parse_scrape(scrape_path)
    entries = registry["metrics"]

    out = []
    w = out.append
    w("# Metric inventory: bff-signup")
    w("")
    w("<!-- Generated by `make metrics-inventory` (.github/scripts/metrics-inventory.py) from the")
    w(f"     Platform Observability Registry in platform-gincommon {gincommon_version} and a real /metrics")
    w("     scrape of this service. Do not edit; CI fails when this file is out of date. -->")
    w("")
    w("Every series carries the centrally injected const labels `domain` (`bff`), `service` "
      "(`bff-signup`) and `environment`. The tables list each metric's own labels only. "
      "Status is the registry's: `approved`, or `proposed` (awaiting observability-governance "
      "ratification). Tier 3 metrics are this service's own and need no registry entry. "
      "See [README.md](README.md) for how the tiers are built, enforced and migrated.")
    w("")

    w("## Tier 1: platform-shared metrics")
    w("")
    w("### Emitted by platform-gincommon")
    w("")
    w("The HTTP server middleware (`gincommon.ObservabilityMiddlewares`) and build info. "
      "This service does not construct these. HTTP series appear once a route has served a request.")
    w("")
    w("| Metric | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|")
    for entry in entries:
        if entry.get("tier") != "platform" or entry.get("owner") not in LIBRARIES:
            continue
        if entry.get("status") == "removed" or entry["name"].startswith("platform_grpc_"):
            continue  # removed names; no gRPC server in this service
        w(f"| `{entry['name']}` | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")
    w("### Built and recorded by this service")
    w("")
    w("Built from the registry with `gincommon.NewSharedHistogramVec` "
      "(`internal/adapter/outbound/metrics/business.go`, `registerShared`), so the name, help, "
      "labels and buckets are the registry's.")
    w("")
    w("| Metric | Owner | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|---|")
    for entry in entries:
        if entry.get("tier") != "platform" or entry.get("owner") in LIBRARIES:
            continue
        if entry["name"] not in scrape:
            continue
        w(f"| `{entry['name']}` | {entry.get('owner', '')} | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")

    w("## Tier 2: BFF domain-shared metrics (`bff_*`)")
    w("")
    domain = [e for e in entries if e.get("tier") == "domain" and e["name"].startswith(DOMAIN_PREFIX)]
    if domain:
        w("| Metric | Type | Status | Labels | Meaning |")
        w("|---|---|---|---|---|")
        for entry in domain:
            w(f"| `{entry['name']}` | {type_cell(entry)} | {entry.get('status', '')} "
              f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    else:
        w("None. The registry has no `bff_*` entries, and bff-signup is the only BFF service, "
          "so nothing is shared within the domain yet.")
    w("")

    w("## Tier 3: service-specific metrics (`bff_signup_*`)")
    w("")
    w("| Metric | Type | Labels | Meaning |")
    w("|---|---|---|---|")
    for name in sorted(n for n in scrape if n.startswith(SERVICE_PREFIX)):
        fam = scrape[name]
        labels = ", ".join(f"`{label}`" for label in sorted(fam["labels"])) or "-"
        w(f"| `{name}` | {fam.get('type', '')} | {labels} | {md(fam.get('help'))} |")
    w("")
    print("\n".join(out))


if __name__ == "__main__":
    main()
